export interface Sensor {
  id: string;
  sensorId: string;
  name: string;
  sensorType: string;
  latitude: number;
  longitude: number;
  ipAddress: string | null;
  rtspUrl: string | null;
  smartMeterId: string | null;
  battery: string | null;
  status: string;
  sendDrone: string;
  activeShuruMode: string;
  areaId: string | null;
  alarmId: string |null;
  createdAt: string;
  updatedAt: string;
  area?: any;
  alarm?: any;
  addedBy?: string;
}

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  count?: number;
  error?: string;
  message?: string;
}

export interface PaginationMeta {
  page: number;
  limit: number;
  totalCount: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

export interface PaginatedApiResponse<T> {
  success: boolean;
  data?: T;
  pagination?: PaginationMeta;
  error?: string;
  message?: string;
}

