export async function getAllSensors(params?: {
  status?: string;
  areaId?: string;
  sensorType?: string;
  include?: boolean;
  page?: number;
  limit?: number;
  search?: string;
}): Promise<PaginatedApiResponse<Sensor[]>> {

  await new Promise((r) => setTimeout(r, 300));

  let data = [...mockSensors];

  if (params?.status) {
    data = data.filter(s => s.status === params.status);
  }

  if (params?.areaId) {
    data = data.filter(s => s.areaId === params.areaId);
  }

  if (params?.sensorType) {
    data = data.filter(s => s.sensorType === params.sensorType);
  }

  if (params?.search) {
    const search = params.search.toLowerCase();

    data = data.filter(
      s =>
        s.name.toLowerCase().includes(search) ||
        s.sensorId.toLowerCase().includes(search) ||
        s.sensorType.toLowerCase().includes(search)
    );
  }

  return {
    success: true,
    data,
    pagination: {
      page: 1,
      limit: data.length,
      totalCount: data.length,
      totalPages: 1,
      hasNextPage: false,
      hasPrevPage: false,
    },
  };
}

export async function getSensorStats(): Promise<ApiResponse<SensorStats>> {

  await new Promise((r) => setTimeout(r, 200));

  return {
    success: true,
    data: {
      total: mockSensors.length,
      active: mockSensors.filter(s => s.status === "Active").length,
      inactive: mockSensors.filter(s => s.status === "Inactive").length,
      warning: mockSensors.filter(s => s.status === "Warning").length,
    },
  };
}
export async function getSensorById(
  id: string,
  includeRelations = false
): Promise<ApiResponse<Sensor>> {
  await new Promise((r) => setTimeout(r, 300));

  const sensor = mockSensors.find((s) => s.id === id);

  if (!sensor) {
    return {
      success: false,
      error: "Sensor not found",
    };
  }

  return {
    success: true,
    data: sensor,
  };
}

export async function getSensorsByArea(
  areaId: string
): Promise<ApiResponse<Sensor[]>> {
  await new Promise((r) => setTimeout(r, 300));

  return {
    success: true,
    count: mockSensors.filter((s) => s.areaId === areaId).length,
    data: mockSensors.filter((s) => s.areaId === areaId),
  };
}

export async function createSensor(sensorData: {
  sensorId: string;
  name: string;
  sensorType: string;
  latitude: number;
  longitude: number;
  ipAddress?: string;
  rtspUrl?: string;
  battery?: string;
  status: string;
  sendDrone?: string;
  activeShuruMode: string;
  areaId?: string;
  alarmId?: string;
  addedBy?: string;
  smartMeterId?: string;
}): Promise<ApiResponse<Sensor>> {
  await new Promise((r) => setTimeout(r, 300));

  const newSensor: Sensor = {
    id: `sensor-${mockSensors.length + 1}`,
    sensorId: sensorData.sensorId,
    name: sensorData.name,
    sensorType: sensorData.sensorType,
    latitude: sensorData.latitude,
    longitude: sensorData.longitude,
    ipAddress: sensorData.ipAddress || null,
    rtspUrl: sensorData.rtspUrl || null,
    smartMeterId: sensorData.smartMeterId || null,
    battery: sensorData.battery || null,
    status: sensorData.status,
    sendDrone: sensorData.sendDrone || "No",
    activeShuruMode: sensorData.activeShuruMode,
    areaId: sensorData.areaId || null,
    alarmId: sensorData.alarmId || null,
    addedBy: sensorData.addedBy || "Demo Admin",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  mockSensors.unshift(newSensor);

  return {
    success: true,
    data: newSensor,
    message: "Sensor created successfully",
  };
}

export async function updateSensor(
  id: string,
  sensorData: Partial<{
    sensorId: string;
    name: string;
    sensorType: string;
    latitude: number;
    longitude: number;
    ipAddress: string;
    rtspUrl: string;
    battery: string;
    status: string;
    sendDrone: string;
    activeShuruMode: string;
    areaId: string;
    alarmId: string;
    smartMeterId: string;
  }>
): Promise<ApiResponse<Sensor>> {
  await new Promise((r) => setTimeout(r, 300));

  const sensor = mockSensors.find((s) => s.id === id);

  if (!sensor) {
    return {
      success: false,
      error: "Sensor not found",
    };
  }

  Object.assign(sensor, sensorData);
  sensor.updatedAt = new Date().toISOString();

  return {
    success: true,
    data: sensor,
    message: "Sensor updated successfully",
  };
}

export async function deleteSensor(
  id: string
): Promise<ApiResponse<null>> {
  await new Promise((r) => setTimeout(r, 300));

  const index = mockSensors.findIndex((s) => s.id === id);

  if (index !== -1) {
    mockSensors.splice(index, 1);
  }

  return {
    success: true,
    message: "Sensor deleted successfully",
  };
}