/* ==================================================
   GET ALL SMART METERS
================================================== */

export async function getAllSmartMeters(params?: {
  status?: string;
  include?: boolean;
  page?: number;
  limit?: number;
  search?: string;
}): Promise<PaginatedApiResponse<SmartMeter[]>> {
  await new Promise((r) => setTimeout(r, 300));

  let data = [...mockSmartMeters];

  if (params?.status) {
    data = data.filter((m) => m.status === params.status);
  }

  if (params?.search) {
    const search = params.search.toLowerCase();

    data = data.filter(
      (m) =>
        m.smartMeterId.toLowerCase().includes(search) ||
        (m.location ?? "").toLowerCase().includes(search) ||
        m.ipAddress.toLowerCase().includes(search)
    );
  }

  return {
    success: true,
    data,
    pagination: {
      page: 1,
      limit: data.length,
      totalCount: data.length,
      totalPages: 1,
      hasNextPage: false,
      hasPrevPage: false,
    },
  };
}

/* ==================================================
   GET SMART METER BY ID
================================================== */

export async function getSmartMeterById(
  id: string,
  includeRelations = false,
): Promise<ApiResponse<SmartMeter>> {
  await new Promise((r) => setTimeout(r, 250));

  const meter = mockSmartMeters.find((m) => m.id === id);

  if (!meter) {
    return {
      success: false,
      error: "Smart Meter not found",
    };
  }

  return {
    success: true,
    data: meter,
  };
}

/* ==================================================
   CREATE SMART METER
================================================== */

export async function createSmartMeter(data: {
  smartMeterId: string;
  location?: string;
  latitude?: number;
  longitude?: number;
  status?: string;
  addedBy?: string;
  ipAddress?: string;
  mediaConverters?: CreateMediaConverter[];
}): Promise<ApiResponse<SmartMeter>> {
  await new Promise((r) => setTimeout(r, 300));

  const newMeter: SmartMeter = {
    id: `meter-${mockSmartMeters.length + 1}`,
    smartMeterId: data.smartMeterId,
    location: data.location || "",
    ipAddress: data.ipAddress || "",
    latitude: data.latitude,
    longitude: data.longitude,
    status: data.status || "Active",
    addedBy: data.addedBy || "Demo Admin",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    sensors: [],
    mediaConverters:
      data.mediaConverters?.map((mc, index) => ({
        id: `mc-${Date.now()}-${index}`,
        mediaConverterId: mc.mediaConverterId,

        left1: false,
        left2: false,
        left3: false,

        right1: false,
        right2: false,
        right3: false,

        left1Label: mc.left1Label,
        left2Label: mc.left2Label,
        left3Label: mc.left3Label,

        right1Label: mc.right1Label,
        right2Label: mc.right2Label,
        right3Label: mc.right3Label,
      })) || [],
  };

  mockSmartMeters.unshift(newMeter);

  return {
    success: true,
    data: newMeter,
    message: "Smart Meter created successfully",
  };
}

/* ==================================================
   UPDATE SMART METER
================================================== */

export async function updateSmartMeter(
  id: string,
  data: Partial<{
    ipAddress: string;
    smartMeterId: string;
    location: string;
    latitude: number;
    longitude: number;
    status: string;
    mediaConverters: {
      id: string;
      mediaConverterId: string;

      left1Label: string;
      left2Label: string;
      left3Label: string;

      right1Label: string;
      right2Label: string;
      right3Label: string;
    }[];
  }>
): Promise<ApiResponse<SmartMeter>> {
  await new Promise((r) => setTimeout(r, 300));

  const meter = mockSmartMeters.find((m) => m.id === id);

  if (!meter) {
    return {
      success: false,
      error: "Smart Meter not found",
    };
  }

  if (data.smartMeterId !== undefined)
    meter.smartMeterId = data.smartMeterId;

  if (data.location !== undefined)
    meter.location = data.location;

  if (data.ipAddress !== undefined)
    meter.ipAddress = data.ipAddress;

  if (data.latitude !== undefined)
    meter.latitude = data.latitude;

  if (data.longitude !== undefined)
    meter.longitude = data.longitude;

  if (data.status !== undefined)
    meter.status = data.status;

  if (data.mediaConverters) {
    meter.mediaConverters = data.mediaConverters.map((mc) => ({
      id: mc.id || `mc-${Date.now()}`,
      mediaConverterId: mc.mediaConverterId,

      left1: false,
      left2: false,
      left3: false,

      right1: false,
      right2: false,
      right3: false,

      left1Label: mc.left1Label,
      left2Label: mc.left2Label,
      left3Label: mc.left3Label,

      right1Label: mc.right1Label,
      right2Label: mc.right2Label,
      right3Label: mc.right3Label,
    }));
  }

  meter.updatedAt = new Date().toISOString();

  return {
    success: true,
    data: meter,
    message: "Smart Meter updated successfully",
  };
}

/* ==================================================
   DELETE SMART METER
================================================== */

export async function deleteSmartMeter(
  id: string
): Promise<ApiResponse<null>> {
  await new Promise((r) => setTimeout(r, 300));

  const index = mockSmartMeters.findIndex((m) => m.id === id);

  if (index === -1) {
    return {
      success: false,
      error: "Smart Meter not found",
    };
  }

  mockSmartMeters.splice(index, 1);

  return {
    success: true,
    message: "Smart Meter deleted successfully",
  };
}