// ==================================================
// GET ALL ALARMS
// ==================================================

export async function getAllAlarms(params?: {
  status?: string;
  areaId?: string;
  include?: boolean;
}): Promise<ApiResponse<Alarm[]>> {
  await new Promise((r) => setTimeout(r, 300));

  let data = [...mockAlarms];

  if (params?.status) {
    data = data.filter((a) => a.status === params.status);
  }

  if (params?.areaId) {
    data = data.filter((a) => a.areaId === params.areaId);
  }

  return {
    success: true,
    count: data.length,
    data,
  };
}

// ==================================================
// GET ALARM BY ID
// ==================================================

export async function getAlarmById(
  id: string,
  includeRelations = false
): Promise<ApiResponse<Alarm>> {
  await new Promise((r) => setTimeout(r, 250));

  const alarm = mockAlarms.find((a) => a.id === id);

  if (!alarm) {
    return {
      success: false,
      error: "Alarm not found",
    };
  }

  return {
    success: true,
    data: alarm,
  };
}

// ==================================================
// GET ALARMS BY AREA
// ==================================================

export async function getAlarmsByArea(
  areaId: string
): Promise<ApiResponse<Alarm[]>> {
  await new Promise((r) => setTimeout(r, 250));

  const alarms = mockAlarms.filter((a) => a.areaId === areaId);

  return {
    success: true,
    count: alarms.length,
    data: alarms,
  };
}

// ==================================================
// GET ALARM SENSORS
// ==================================================

export async function getAlarmSensors(
  id: string
): Promise<ApiResponse<any[]>> {
  await new Promise((r) => setTimeout(r, 200));

  const alarm = mockAlarms.find((a) => a.id === id);

  if (!alarm) {
    return {
      success: false,
      error: "Alarm not found",
    };
  }

  return {
    success: true,
    count: alarm.sensors?.length || 0,
    data: alarm.sensors || [],
  };
}

// ==================================================
// CREATE ALARM
// ==================================================

export async function createAlarm(alarmData: {
  alarmId: string;
  name: string;
  status?: string;
  areaId?: string;
}): Promise<ApiResponse<Alarm>> {
  await new Promise((r) => setTimeout(r, 300));

  const newAlarm: Alarm = {
    id: `alarm-${mockAlarms.length + 1}`,
    alarmId: alarmData.alarmId,
    name: alarmData.name,
    status: alarmData.status || "Active",
    areaId: alarmData.areaId || null,

    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),

    area:
      alarmData.areaId === "area-1"
        ? {
            id: "area-1",
            areaId: "AREA-001",
            name: "North Zone",
            latitude: 28.6139,
            longitude: 77.209,
            status: "Active",
          }
        : alarmData.areaId === "area-2"
        ? {
            id: "area-2",
            areaId: "AREA-002",
            name: "South Zone",
            latitude: 28.5355,
            longitude: 77.391,
            status: "Active",
          }
        : alarmData.areaId === "area-3"
        ? {
            id: "area-3",
            areaId: "AREA-003",
            name: "East Zone",
            latitude: 28.7041,
            longitude: 77.1025,
            status: "Inactive",
          }
        : undefined,

    sensors: [],
  };

  mockAlarms.unshift(newAlarm);

  return {
    success: true,
    data: newAlarm,
    message: "Alarm created successfully",
  };
}

// ==================================================
// UPDATE ALARM
// ==================================================

export async function updateAlarm(
  id: string,
  alarmData: Partial<{
    alarmId: string;
    name: string;
    status: string;
    areaId: string;
  }>
): Promise<ApiResponse<Alarm>> {
  await new Promise((r) => setTimeout(r, 300));

  const alarm = mockAlarms.find((a) => a.id === id);

  if (!alarm) {
    return {
      success: false,
      error: "Alarm not found",
    };
  }

  Object.assign(alarm, alarmData);

  if (alarmData.areaId !== undefined) {
    if (alarmData.areaId === "area-1") {
      alarm.area = {
        id: "area-1",
        areaId: "AREA-001",
        name: "North Zone",
        latitude: 28.6139,
        longitude: 77.209,
        status: "Active",
      };
    } else if (alarmData.areaId === "area-2") {
      alarm.area = {
        id: "area-2",
        areaId: "AREA-002",
        name: "South Zone",
        latitude: 28.5355,
        longitude: 77.391,
        status: "Active",
      };
    } else if (alarmData.areaId === "area-3") {
      alarm.area = {
        id: "area-3",
        areaId: "AREA-003",
        name: "East Zone",
        latitude: 28.7041,
        longitude: 77.1025,
        status: "Inactive",
      };
    } else {
      alarm.area = undefined;
    }
  }

  alarm.updatedAt = new Date().toISOString();

  return {
    success: true,
    data: alarm,
    message: "Alarm updated successfully",
  };
}

// ==================================================
// DELETE ALARM
// ==================================================

export async function deleteAlarm(
  id: string
): Promise<ApiResponse<null>> {
  await new Promise((r) => setTimeout(r, 300));

  const index = mockAlarms.findIndex((a) => a.id === id);

  if (index === -1) {
    return {
      success: false,
      error: "Alarm not found",
    };
  }

  mockAlarms.splice(index, 1);

  return {
    success: true,
    message: "Alarm deleted successfully",
  };
}