export interface Area {
  id: string;
  areaId: string;
  name: string;
  latitude: number;
  longitude: number;
  status: string;
  createdAt: string;
  updatedAt: string;
  addedBy: string;
  sensors?: any[];
  alarms?: any[];
  drones?: any[];
}

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  count?: number;
  error?: string;
  message?: string;
}

export interface PaginationMeta {
  page: number;
  limit: number;
  totalCount: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

export interface PaginatedApiResponse<T> {
  success: boolean;
  data?: T;
  pagination?: PaginationMeta;
  error?: string;
  message?: string;
}

