export async function getAllAreas(params?: {
  status?: string;
  include?: boolean;
  page?: number;
  limit?: number;
  search?: string;
}): Promise<PaginatedApiResponse<Area[]>> {
  await new Promise((r) => setTimeout(r, 300));

  let data = [...mockAreas];

  if (params?.status) {
    data = data.filter((a) => a.status === params.status);
  }

  if (params?.search) {
    const search = params.search.toLowerCase();
    data = data.filter(
      (a) =>
        a.name.toLowerCase().includes(search) ||
        a.areaId.toLowerCase().includes(search)
    );
  }

  return {
    success: true,
    data,
    pagination: {
      page: 1,
      limit: data.length,
      totalCount: data.length,
      totalPages: 1,
      hasNextPage: false,
      hasPrevPage: false,
    },
  };
}

export async function getAreaById(
  id: string,
  includeRelations = false
): Promise<ApiResponse<Area>> {
  await new Promise((r) => setTimeout(r, 300));

  const area = mockAreas.find((a) => a.id === id);

  if (!area) {
    return {
      success: false,
      error: "Area not found",
    };
  }

  return {
    success: true,
    data: area,
  };
}

export async function createArea(areaData: {
  areaId: string;
  name: string;
  latitude: number;
  longitude: number;
  addedBy?: string;
  status?: string;
}): Promise<ApiResponse<Area>> {
  await new Promise((r) => setTimeout(r, 300));

  const newArea: Area = {
    id: `area-${mockAreas.length + 1}`,
    areaId: areaData.areaId,
    name: areaData.name,
    latitude: areaData.latitude,
    longitude: areaData.longitude,
    status: areaData.status || "Active",
    addedBy: areaData.addedBy || "Demo Admin",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    sensors: [],
    alarms: [],
    drones: [],
  };

  mockAreas.unshift(newArea);

  return {
    success: true,
    data: newArea,
    message: "Area created successfully",
  };
}

export async function updateArea(
  id: string,
  areaData: Partial<{
    areaId: string;
    name: string;
    latitude: number;
    longitude: number;
    status: string;
  }>
): Promise<ApiResponse<Area>> {
  await new Promise((r) => setTimeout(r, 300));

  const area = mockAreas.find((a) => a.id === id);

  if (!area) {
    return {
      success: false,
      error: "Area not found",
    };
  }

  Object.assign(area, areaData);
  area.updatedAt = new Date().toISOString();

  return {
    success: true,
    data: area,
    message: "Area updated successfully",
  };
}

export async function deleteArea(
  id: string
): Promise<ApiResponse<null>> {
  await new Promise((r) => setTimeout(r, 300));

  const index = mockAreas.findIndex((a) => a.id === id);

  if (index !== -1) {
    mockAreas.splice(index, 1);
  }

  return {
    success: true,
    message: "Area deleted successfully",
  };
}